//! Checks terrain heights and blocks against the real Java `PlanetTerrain`
//! (golden generated by tests/GoldTerrain.java.txt, seed 12345).
use universe::terrain::{block, height, surface_height};
use universe::{SystemId, UniverseCatalog};

#[test]
fn terrain_matches_java_golden() {
    let golden = include_str!("terrain_golden.txt");
    let mut cat = UniverseCatalog::new(12345);
    let mut columns = 0;
    let mut blocks = 0;
    for line in golden.lines().filter(|l| l.starts_with("H ")) {
        let f: Vec<&str> = line.split(' ').collect();
        let id: Vec<i64> = f[1].split(',').map(|v| v.parse().unwrap()).collect();
        let body: usize = f[2].parse().unwrap();
        let (x, z): (i32, i32) = (f[3].parse().unwrap(), f[4].parse().unwrap());
        let (h, sh): (i32, i32) = (f[5].parse().unwrap(), f[6].parse().unwrap());
        let p = cat.system(SystemId { x: id[0], y: id[1], z: id[2] }).bodies[body].clone();
        assert_eq!(height(&p, x, z), h, "height: {line}");
        assert_eq!(surface_height(&p, x, z), sh, "surface height: {line}");
        columns += 1;
        for entry in &f[7..] {
            let (y, name) = entry.split_once(':').unwrap();
            let y: i32 = y.parse().unwrap();
            assert_eq!(block(&p, x, y, z, h).name(), name, "block y={y}: {line}");
            blocks += 1;
        }
    }
    assert!(columns > 100 && blocks > 1500, "{columns} columns, {blocks} blocks");
}
